// 只核完整域史先验后的知情投影，不冒实际采购和履约旅程。
void firsthand_projection(){
 PrivateShopState state;PrivateShopRecord shop;shop.id="private_shop:1";shop.terms.proprietor_actor_id="owner";state.shops.insert(shop.id,shop);
 PrivateShopPurchaseFact purchase;purchase.id="private_shop_stock:2";purchase.shop_id=shop.id;state.purchases.insert(purchase.id,purchase);
 PrivateShopOperation op;op.id="action:3";op.shop_id=shop.id;op.actor_id="worker";state.operations.insert(op.id,op);
 PrivateShopDayResult day;day.id="private_shop_day:4";day.operation_id=op.id;day.shop_id=shop.id;day.actor_id="worker";state.operating_results.insert(day.id,day);
 check(private_shop_history_is_firsthand(state,"owner",shop.id)&&private_shop_history_is_firsthand(state,"owner",purchase.id),"original opening and personally purchased goods remain known");
 check(!private_shop_history_is_firsthand(state,"worker",purchase.id)&&!private_shop_history_is_firsthand(state,"owner",day.id),"ownership does not reveal later worker operation remotely");
 check(private_shop_history_is_firsthand(state,"worker",day.id),"actual worker retains firsthand completed work");
 state.operating_results.find(day.id)->actor_id="owner";check(!private_shop_history_is_firsthand(state,"owner",day.id),"result actor cannot replace original operation actor");
 PrivateShopStaffTermination ended;ended.id="private_shop_staff_decision:5";ended.actor_id="owner";ended.decision="dismissed";state.staff.decisions.insert(ended.id,ended);check(private_shop_history_is_firsthand(state,"owner",ended.id)&&!private_shop_history_is_firsthand(state,"worker",ended.id),"own dismissal remains known without revealing the other party's decision remotely");state.staff.decisions.find(ended.id)->actor_id.clear();state.staff.decisions.find(ended.id)->decision="worker_dead";check(!private_shop_history_is_firsthand(state,"owner",ended.id),"automatic remote death is not a personally issued decision");
 check(!private_shop_history_is_firsthand(state,"owner","missing"),"missing source is not a personal document");
}
// 此组仅核已验证来源的成本投影算法，不冒下面真实开设或原订单交货资金门。
void purchase_cost_projection(){
 PrivateShopState state;PrivateShopPurchaseFact purchase;purchase.id="private_shop_stock:1";purchase.shop_id="private_shop:1";purchase.item_id="grain";purchase.quantity=3;purchase.purchase_cash=10;state.purchases.insert(purchase.id,purchase);auto& original=*state.purchases.find(purchase.id);
 auto value=derive_private_shop_purchase_cost_view(state,original);check(value.ok&&value.value.sold_quantity==0&&value.value.recognized_cost==0&&value.value.unrecognized_quantity==3&&value.value.unrecognized_cost==10,"unsold purchase remains cost asset not immediate operating expense");check(!derive_private_shop_purchase_cost_view(state,purchase).ok,"detached purchase payload is not original state source");
 PrivateShopDayResult day;day.id="private_shop_day:2";day.shop_id=purchase.shop_id;day.consumed_lots.push_back({purchase.id,"lot:2",1,3});state.operating_results.insert(day.id,day);PrivateShopOrderRecord order;order.id="private_shop_order:3";order.terms.shop_id=purchase.shop_id;state.orders.orders.insert(order.id,order);PrivateShopOrderSettlement settlement;settlement.id="private_shop_order_settlement:4";settlement.order_id=order.id;settlement.consumed_lots.push_back({purchase.id,"lot:2",1,3});state.order_settlements.insert(settlement.id,settlement);
 value=derive_private_shop_purchase_cost_view(state,original);check(value.ok&&value.value.sold_quantity==2&&value.value.recognized_cost==6&&value.value.unrecognized_quantity==1&&value.value.unrecognized_cost==4,"retail and actual order shares retain final rounding remainder");PrivateShopClosingRecord closing;closing.id="private_shop_closed:5";closing.shop_id=purchase.shop_id;closing.returned_lots.push_back({"lot:2","lot:6","grain",1});state.closings.insert(closing.id,closing);value=derive_private_shop_purchase_cost_view(state,original);check(value.ok&&value.value.unrecognized_cost==4,"returning original unsold goods is not a sale or expense");
 state.order_settlements.find(settlement.id)->consumed_lots.front().cost=2;check(!derive_private_shop_purchase_cost_view(state,original).ok,"self-total that contradicts unique cumulative slice rejected");state.order_settlements.find(settlement.id)->consumed_lots.front().cost=3;state.operating_results.find(day.id)->shop_id="other";check(!derive_private_shop_purchase_cost_view(state,original).ok,"another shop cannot consume this original purchase cost");state.operating_results.find(day.id)->shop_id=purchase.shop_id;
 state.order_settlements.find(settlement.id)->consumed_lots.front().quantity=2;state.order_settlements.find(settlement.id)->consumed_lots.front().cost=7;value=derive_private_shop_purchase_cost_view(state,original);check(value.ok&&value.value.sold_quantity==3&&value.value.recognized_cost==10&&value.value.unrecognized_cost==0,"last sold unit absorbs complete original cost exactly once");state.order_settlements.find(settlement.id)->consumed_lots.front().quantity=3;check(!derive_private_shop_purchase_cost_view(state,original).ok,"overconsumed original cost cannot become negative balance");
}
