 auto before=encode_common_state(f.common.state());auto local=query_private_shop_business(x,"owner",{"premises"});check(local.ok&&local.value.find("rows")->as<V::Array>()->size()==1,"only current local premises");check(compare_boundary(before,encode_common_state(f.common.state())).exact(),"query and actual quotes never spend or allocate IDs");check(!query_private_shop_business(x,"lessor",{}).ok,"another actor cannot use player query");auto opened=open_private_shop(f.common,f.economy,f.state,f.context(),f.meeting(),f.quote());check(opened.ok,"open actual shop before owner page");auto own=query_private_shop_business(x,"owner",{});check(own.ok&&own.value.find("rows")->as<V::Array>()->size()==1,"actual owner shop visible");const auto& row=own.value.find("rows")->as<V::Array>()->front();check(*row.find("cash")->as<Integer>()==300&&*row.find("completed_orders")->as<Integer>()==0&&!*row.find("milestone_reached")->as<bool>(),"capital is not realized profit or milestone");check(!query_private_shop_business(x,"owner",{"shop","unknown"}).ok,"unknown selected shop rejected");auto detail=query_private_shop_business(x,"owner",{"shop",opened.value.shop_id});check(detail.ok,"business actions reuse actual preview");const auto& goods=detail.value.find("rows")->as<V::Array>()->back();const auto& operation=goods.find("actions")->as<V::Array>()->front();check(!*operation.find("available")->as<bool>()&&*operation.find("code")->as<StableId>()=="PrivateShopMarketHistoryUnavailable","unproven market cannot become enabled business action");
 // 本金由真实资金recipe逐笔进入店金，账页只投影永久源并按同tick真实事实序分页。
 check(decode_private_shop_business_query(obj({{"tab",V{"ledger"}}})).ok,"ledger query admitted");
 StableId newest;for(Integer amount=1;amount<=17;++amount){auto q=preview_private_shop_management(f.context(),"owner",PrivateShopFund{opened.value.shop_id,amount});check(q.ok,"actual capital quote for ledger");auto r=manage_private_shop(f.common,f.state,f.context(),q.value);check(r.ok,"actual capital source for ledger");newest=r.value;}
 const auto frozen=encode_common_state(f.common.state()),shop_state=encode_private_shop_state(f.state);auto ledger=query_private_shop_business(x,"owner",{"ledger",opened.value.shop_id});check(ledger.ok,"own permanent ledger");const auto& recent=*ledger.value.find("rows")->as<V::Array>();check(recent.size()==16&&*ledger.value.find("next_cursor")->as<Integer>()==16,"ledger has bounded sixteen rows");check(*recent.front().find("id")->as<StableId>()==newest&&*recent.front().find("amount")->as<Integer>()==17,"newest actual same-tick fact first");check(!recent.front().find("income")&&!recent.front().find("net_income"),"capital does not become realized income");
 auto older=query_private_shop_business(x,"owner",{"ledger",opened.value.shop_id,16});check(older.ok&&!older.value.find("next_cursor"),"last ledger page bounded");const auto& old=*older.value.find("rows")->as<V::Array>();check(old.size()==2&&*old.back().find("record_kind")->as<StableId>()=="opening","real opening remains oldest entry");check(*old.back().find("opening_fee")->as<Integer>()==900&&*old.back().find("initial_capital")->as<Integer>()==300,"opening fee and seed capital remain distinct");check(!query_private_shop_business(x,"owner",{"ledger","unknown"}).ok&&!query_private_shop_business(x,"lessor",{"ledger",opened.value.shop_id}).ok,"ledger requires actual proprietor");check(!query_private_shop_business(x,"owner",{"ledger",opened.value.shop_id,19}).ok,"ledger cursor beyond actual sources rejected");check(compare_boundary(frozen,encode_common_state(f.common.state())).exact()&&compare_boundary(shop_state,encode_private_shop_state(f.state)).exact(),"ledger preserves all assets facts IDs and shop ledger");
// 同城不同铺位仍是远方；离开后保留本人原始凭据。
 f.common_catalog->places.insert("courtyard",{"courtyard","town",{}});f.common.state().actors.find("owner")->location=SettlementLocation{"town","courtyard"};
