 auto remote_detail=query_private_shop_business(x,"owner",{"shop",opened.value.shop_id});check(remote_detail.ok&&remote_detail.value.find("rows")->as<V::Array>()->size()==1&&remote_detail.value.find("rows")->as<V::Array>()->front().find("actions")->as<V::Array>()->empty(),"remote detail never previews live stock or management");
