 auto remote_open=query_private_shop_business(x,"owner",{"ledger",opened.value.shop_id,16});check(remote_open.ok&&compare_boundary(*remote_open.value.find("rows"),*older.value.find("rows")).exact(),"remote opening keeps original fee and capital");
 check(compare_boundary(remote_before,encode_common_state(f.common.state())).exact()&&compare_boundary(shop_state,encode_private_shop_state(f.state)).exact(),"remote observation never writes money facts or report state");
